import {useEffect,useMemo,useState} from 'react'
import { Area,AreaChart, BarChart,Bar,LabelList,PieChart,Pie,Cell,ResponsiveContainer,Tooltip,XAxis,YAxis,CartesianGrid,Legend,ScatterChart,Scatter,ComposedChart,Line } from 'recharts'
import { Download, Moon, Sun, RefreshCw, DollarSign, TrendingUp, TrendingDown, Activity, ShoppingCart, Users, Truck, Clock, Filter, CalendarDays, Globe2, MapPin, Tags, ClipboardCheck, ReceiptText, X, CircleDollarSign, TriangleAlert, Package, Target } from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import {useRetailData} from '../hooks/useRetailData'; import type {Filters,RetailRow} from '../types/retail'; import {group} from '../utils/dataProcessing'; import {money,number,pct,fullMoney} from '../utils/formatting'; import {marginThresholds,marginTone} from '../utils/tableSemantics'; import {displayCountryName} from '../utils/countryNames'; import {KPICard} from '../components/KPICard'; import {ChartCard} from '../components/ChartCard'; import {OpportunityMatrix} from '../components/OpportunityMatrix'; import {GlobalSalesMap} from '../components/GlobalSalesMap'; import {PredictiveAnalytics} from '../components/PredictiveAnalytics'
const colors=['#2563eb','#16a34a','#f59e0b','#8b5cf6','#ef4444','#06b6d4']; const blank:Filters={year:'All',market:'All',region:'All',segment:'All',category:'All',shippingMode:'All',deliveryStatus:'All',orderStatus:'All',search:''};
const navigation=[['Overview','overview'],['Sales','sales'],['Products','products'],['Customers','customers'],['Geography','geography'],['Supply Chain','supply-chain'],['Profitability','profitability'],['Predictive Analytics','predictive-analytics']] as const;
const uniq=(rows:RetailRow[],f:(r:RetailRow)=>string)=>['All',...Array.from(new Set(rows.map(f))).sort()];
const opts=(label:string,allLabel:string,value:string,values:string[],set:(v:string)=>void,Icon:LucideIcon)=><label className={value==='All'?'':'is-active'}><span className="filter-label"><Icon size={13}/>{label}</span><select value={value} onChange={e=>set(e.target.value)}>{values.map(x=><option key={x} value={x}>{x==='All'?allLabel:x}</option>)}</select></label>;
type InsightCardData={tone:'sales'|'profit'|'market'|'risk'|'customers';label:string;entity:string;metric:string;context:string;Icon:LucideIcon};
type MomentumState='accelerating'|'growing'|'stable'|'softening'|'declining';type SalesMomentum={change:number;state:MomentumState;latest:string;previous:string;spark:number[]};type SalesIntelligence={topCategory?:{name:string;value:number};runnerUp?:{name:string;value:number};topProduct?:ProductRow;concentration:number;momentum?:SalesMomentum;concentrationLabel:string;concentrationTone:'low'|'moderate'|'high'|'very-high';concentrationMeaning:string;categoryFiltered:boolean};
const TrendTooltip=({active,payload,label}:{active?:boolean;payload?:{dataKey?:string;value?:number;color?:string}[];label?:string})=>active&&payload?.length?<div className="trend-tooltip"><strong>{label}</strong>{payload.map(item=><span key={item.dataKey}><i style={{background:item.color}}/>{item.dataKey==='orders'||item.dataKey==='quantity'?item.dataKey[0].toUpperCase()+item.dataKey.slice(1):item.dataKey==='margin'?'Profit margin':item.dataKey==='sales'?'Sales':'Profit'} <b>{item.dataKey==='orders'||item.dataKey==='quantity'?number(item.value||0):item.dataKey==='margin'?pct(item.value||0):fullMoney(item.value||0)}</b></span>)}</div>:null;
export default function Dashboard(){const {data,error,loading,progress}=useRetailData(); const [filters,setFilters]=useState(blank);const [dark,setDark]=useState(false); const [period,setPeriod]=useState('Monthly');const [trendMetric,setTrendMetric]=useState('Sales & Profit');const [page,setPage]=useState(0);const getActiveHash=()=>navigation.some(([,hash])=>`#${hash}`===location.hash)?location.hash.slice(1):'overview';const [activeNav,setActiveNav]=useState(getActiveHash);useEffect(()=>{const sync=()=>setActiveNav(getActiveHash());addEventListener('hashchange',sync);sync();return()=>removeEventListener('hashchange',sync)},[]);const set=(key:keyof Filters)=>(value:string)=>{setFilters(f=>({...f,[key]:value}));setPage(0)};
 const rows=useMemo(()=>data.filter(r=>(filters.year==='All'||String(r.date.getFullYear())===filters.year)&&(filters.market==='All'||r.market===filters.market)&&(filters.region==='All'||r.region===filters.region)&&(filters.segment==='All'||r.segment===filters.segment)&&(filters.category==='All'||r.category===filters.category)&&(filters.shippingMode==='All'||r.shippingMode===filters.shippingMode)&&(filters.deliveryStatus==='All'||r.deliveryStatus===filters.deliveryStatus)&&(filters.orderStatus==='All'||r.orderStatus===filters.orderStatus)&&(!filters.search||r.product.toLowerCase().includes(filters.search.toLowerCase()))),[data,filters]);
 const summary=useMemo(()=>{const sales=rows.reduce((a,r)=>a+r.sales,0),profit=rows.reduce((a,r)=>a+r.profit,0),orders=new Set(rows.map(r=>r.orderId)).size,customers=new Set(rows.map(r=>r.customerId)).size;return{sales,profit,orders,customers,late:rows.filter(r=>r.late===1).length/(rows.length||1)}},[rows]);
 const monthly=useMemo(()=>{const map=new Map<string,{name:string;sales:number;profit:number;quantity:number;late:number;rows:number;orders:Set<string>;customers:Set<string>}>(); rows.forEach(r=>{const d=r.date;let k=period==='Yearly'?`${d.getFullYear()}`:period==='Quarterly'?`${d.getFullYear()} Q${Math.floor(d.getMonth()/3)+1}`:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;const x=map.get(k)||{name:k,sales:0,profit:0,quantity:0,late:0,rows:0,orders:new Set<string>(),customers:new Set<string>()};x.sales+=r.sales;x.profit+=r.profit;x.quantity+=r.quantity;x.late+=r.late;x.rows++;x.orders.add(r.orderId);x.customers.add(r.customerId);map.set(k,x)});return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name)).map(x=>({...x,orders:x.orders.size,customers:x.customers.size,margin:x.profit/(x.sales||1),aov:x.sales/(x.orders.size||1),lateRate:x.late/(x.rows||1)}))},[rows,period]);
 const salesMomentum=useMemo<SalesMomentum|undefined>(()=>{if(monthly.length<2)return undefined;const previous=monthly[monthly.length-2],latest=monthly[monthly.length-1];if(previous.sales===0)return undefined;const change=(latest.sales-previous.sales)/previous.sales,state:MomentumState=change>.05?'accelerating':change>.01?'growing':change>=-.01?'stable':change>=-.05?'softening':'declining';return{change,state,latest:latest.name,previous:previous.name,spark:monthly.slice(-8).map(item=>item.sales)}},[monthly]);
 const cats=useMemo(()=>group(rows,r=>r.category,r=>r.sales),[rows]); const profits=useMemo(()=>group(rows,r=>r.category,r=>r.profit),[rows]);const segments=useMemo(()=>group(rows,r=>r.segment,r=>r.sales),[rows]);const markets=useMemo(()=>group(rows,r=>r.market,r=>r.sales),[rows]);const countries=useMemo(()=>group(rows,r=>displayCountryName(r.country),r=>r.sales).slice(0,10),[rows]);const products=useMemo(()=>group(rows,r=>r.product,r=>r.sales).slice(0,10),[rows]);const statuses=useMemo(()=>group(rows,r=>r.orderStatus,()=>1),[rows]);const delivery=useMemo(()=>group(rows,r=>r.deliveryStatus,()=>1),[rows]);
 const productRows=useMemo(()=>{const m=new Map<string,{name:string;category:string;sales:number;profit:number;quantity:number}>();rows.forEach(r=>{const x=m.get(r.product)||{name:r.product,category:r.category,sales:0,profit:0,quantity:0};x.sales+=r.sales;x.profit+=r.profit;x.quantity+=r.quantity;m.set(r.product,x)});return [...m.values()].sort((a,b)=>b.sales-a.sales)},[rows]);const ship=useMemo(()=>uniq(rows,r=>r.shippingMode).slice(1).map(name=>{const x=rows.filter(r=>r.shippingMode===name);return{name,orders:new Set(x.map(r=>r.orderId)).size,days:x.reduce((a,r)=>a+r.actualDays,0)/(x.length||1),late:x.filter(r=>r.late===1).length/(x.length||1)}}),[rows]);const insightCards=useMemo<InsightCardData[]>(()=>{const risk=[...ship].sort((a,b)=>b.late-a.late)[0],items:InsightCardData[]=[];if(cats[0])items.push({tone:'sales',label:'Sales leader',entity:cats[0].name,metric:`${money(cats[0].value)} in sales`,context:'Highest-selling category',Icon:TrendingUp});if(profits[0])items.push({tone:'profit',label:'Profitability leader',entity:profits[0].name,metric:`${money(profits[0].value)} profit`,context:'Highest-profit category',Icon:CircleDollarSign});if(markets[0])items.push({tone:'market',label:'Market leader',entity:markets[0].name,metric:`${money(markets[0].value)} sales`,context:'Leading market contribution',Icon:Globe2});if(risk)items.push({tone:'risk',label:'Delivery risk',entity:risk.name,metric:`${pct(risk.late)} late delivery`,context:'Highest late-delivery rate',Icon:TriangleAlert});if(segments[0])items.push({tone:'customers',label:'Customer segment',entity:segments[0].name,metric:`${money(segments[0].value)} sales`,context:'Largest customer contribution',Icon:Users});return items},[cats,profits,markets,segments,ship]);const salesIntelligence=useMemo<SalesIntelligence>(()=>{const concentration=productRows.slice(0,10).reduce((sum,item)=>sum+item.sales,0)/(summary.sales||1),categoryFiltered=filters.category!=='All',concentrationTone=concentration>.85?'very-high':concentration>=.7?'high':concentration>=.5?'moderate':'low',concentrationLabel=concentrationTone==='very-high'?'Very high concentration':concentrationTone==='high'?'High concentration':concentrationTone==='moderate'?'Moderate concentration':'Low concentration',baseMeaning=concentrationTone==='very-high'?'Revenue is heavily concentrated among the leading products.':concentrationTone==='high'?'Revenue is concentrated among a relatively small group of leading products.':concentrationTone==='moderate'?'Revenue is moderately distributed across leading products.':'Revenue is relatively distributed across products.',momentumMeaning=salesMomentum?(salesMomentum.state==='accelerating'||salesMomentum.state==='growing'?' Sales are increasing relative to the previous period.':salesMomentum.state==='softening'||salesMomentum.state==='declining'?' Recent sales are declining relative to the previous period.':' Recent sales are relatively stable.'):'',concentrationMeaning=baseMeaning+momentumMeaning;return{topCategory:cats[0],runnerUp:cats[1],topProduct:productRows[0],concentration,momentum:salesMomentum,concentrationTone,concentrationLabel,concentrationMeaning,categoryFiltered}},[cats,filters.category,productRows,salesMomentum,summary.sales]);
 const exportCSV=()=>{const csv=['Order Id,Date,Sales,Profit,Category,Market,Shipping Mode',...rows.map(r=>[r.orderId,r.date.toISOString(),r.sales,r.profit,JSON.stringify(r.category),JSON.stringify(r.market),JSON.stringify(r.shippingMode)].join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='dataco-filtered-summary.csv';a.click();URL.revokeObjectURL(a.href)}; const activeFilters=([{key:'year',label:'Year',value:filters.year},{key:'market',label:'Market',value:filters.market},{key:'region',label:'Region',value:filters.region},{key:'segment',label:'Segment',value:filters.segment},{key:'category',label:'Category',value:filters.category},{key:'shippingMode',label:'Shipping',value:filters.shippingMode},{key:'deliveryStatus',label:'Delivery',value:filters.deliveryStatus},{key:'orderStatus',label:'Order status',value:filters.orderStatus}] as {key:keyof Filters;label:string;value:string}[]).filter(item=>item.value!=='All'); const active=activeFilters.length; const connection=error?{tone:'error',label:'Connection error'}:loading?{tone:'loading',label:'Loading...'}:{tone:'connected',label:'Connected'};
 if(error)return <main className="error"><h1>Unable to load retail dataset</h1><p>{error}</p><button onClick={()=>location.reload()}>Retry</button></main>; if(loading)return <main className="loading" aria-live="polite"><RefreshCw className="spin"/><h1>Loading DataCo retail data…</h1><p>{progress.phase}{progress.rows?` — ${number(progress.rows)} rows processed`:''}</p><p>{progress.percent}% complete</p></main>; if(!data.length)return <main className="error"><h1>No usable retail records were found</h1><p>The CSV was read, but no valid records were available for analysis.</p></main>;
 return <main className={dark?'app dark':'app'}><header><div><h1>DataCo Retail Analytics</h1><p>Sales, Profitability &amp; Supply Chain Performance</p></div><div className="header-actions"><span className="status"><i/> {number(data.length)} records loaded</span><button className="icon" onClick={()=>setDark(!dark)} aria-label="Toggle theme">{dark?<Sun/>:<Moon/>}</button></div></header><nav><div className="sidebar-brand"><strong>DataCo</strong><span>Retail Analytics</span><div className="sidebar-author"><small>Made by</small><b>Kliz John Andrei C. Millares</b></div></div><span className="sidebar-workspace">Workspace</span>{navigation.map(([label,hash])=><a key={hash} className={activeNav===hash?'active':''} href={`#${hash}`}>{label}</a>)}<div className="sidebar-status" aria-live="polite"><span className="sidebar-status-title">Data status</span><span className={`connection-state ${connection.tone}`}><i aria-hidden="true"/>{connection.label}</span><span className="sidebar-records">{number(data.length)} records</span><span className="sidebar-export">↧&nbsp; Export filtered data</span></div></nav>
 <section className="filters" aria-label="Global dashboard filters"><div className="filter-intro"><div className="filter-title"><Filter size={19}/><div><strong>Filters</strong><small>Refine the data across all dashboards</small></div></div><span className={active?'active-filter-count':'active-filter-count idle'}>{active} {active===1?'filter':'filters'} active</span></div><div className="filter-controls">{opts('Year','All Years',filters.year,uniq(data,r=>String(r.date.getFullYear())),set('year'),CalendarDays)}{opts('Market','All Markets',filters.market,uniq(data,r=>r.market),set('market'),Globe2)}{opts('Region','All Regions',filters.region,uniq(data,r=>r.region),set('region'),MapPin)}{opts('Segment','All Segments',filters.segment,uniq(data,r=>r.segment),set('segment'),Users)}{opts('Category','All Categories',filters.category,uniq(data,r=>r.category),set('category'),Tags)}{opts('Shipping','All Modes',filters.shippingMode,uniq(data,r=>r.shippingMode),set('shippingMode'),Truck)}{opts('Delivery','All Statuses',filters.deliveryStatus,uniq(data,r=>r.deliveryStatus),set('deliveryStatus'),ClipboardCheck)}{opts('Order status','All Statuses',filters.orderStatus,uniq(data,r=>r.orderStatus),set('orderStatus'),ReceiptText)}</div><div className="filter-footer"><div className="filter-summary">{active?<><span className="filter-summary-label">Active filters</span><div className="filter-chips">{activeFilters.map(item=><button key={item.key} className="filter-chip" onClick={()=>set(item.key)('All')} aria-label={`Remove ${item.label}: ${item.value}`}><span>{item.label}: <b>{item.value}</b></span><X size={13}/></button>)}</div></>:<div className="filter-empty"><strong>No filters applied</strong><span>Refine the data using the controls above.</span></div>}</div><div className="filter-actions"><button className="reset" onClick={()=>setFilters(blank)} disabled={!active}>Clear all</button><button className="export" onClick={exportCSV}><Download size={16}/> Export filtered data</button></div></div></section>
 {rows.length===0?<section className="empty"><h2>No data available for the selected filters.</h2><button onClick={()=>setFilters(blank)}>Reset Filters</button></section>:<><section className="kpis" id="overview"><KPICard label="Total Sales" value={money(summary.sales)} detail="Sum of Sales" Icon={DollarSign} data={monthly} dataKey="sales" variant="sales"/><KPICard label="Total Profit" value={money(summary.profit)} detail="Sum of order profit" Icon={TrendingUp} data={monthly} dataKey="profit" variant="profit"/><KPICard label="Total Orders" value={number(summary.orders)} detail="Distinct Order Id" Icon={ShoppingCart} data={monthly} dataKey="orders" variant="orders"/><KPICard label="Total Customers" value={number(summary.customers)} detail="Distinct Customer Id" Icon={Users} data={monthly} dataKey="customers" variant="customers"/><KPICard label="Avg. Order Value" value={money(summary.sales/(summary.orders||1))} detail="Sales / unique orders" Icon={DollarSign} data={monthly} dataKey="aov" variant="aov"/><KPICard label="Late Delivery Rate" value={pct(summary.late)} detail="Rows flagged at risk" Icon={Clock} data={monthly} dataKey="lateRate" variant="risk"/></section>
 <section id="overview-performance"><h2>Business Performance</h2><p className="section-description">Executive view of revenue, profitability, customers, and operational performance.</p><div className="grid two overview-grid"><ChartCard title="Sales & Profit Trend" className="overview-trend"><div className="chart-controls"><select aria-label="Trend metric" value={trendMetric} onChange={e=>setTrendMetric(e.target.value)}>{['Sales & Profit','Sales','Profit','Orders','Quantity'].map(x=><option key={x}>{x}</option>)}</select><select aria-label="Time granularity" value={period} onChange={e=>setPeriod(e.target.value)}>{['Monthly','Quarterly','Yearly'].map(x=><option key={x}>{x}</option>)}</select></div><p className="chart-description">Movement across the selected period. Hover to compare performance metrics.</p><ResponsiveContainer width="100%" height={300}><AreaChart data={monthly}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="name" minTickGap={28}/><YAxis yAxisId="left" tickFormatter={trendMetric==='Orders'||trendMetric==='Quantity'?number:money}/>{trendMetric==='Sales & Profit'&&<YAxis yAxisId="right" orientation="right" tickFormatter={money}/>}<Tooltip content={<TrendTooltip/>}/><Legend/>{trendMetric==='Sales & Profit'?<><Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" fill="#3b82f624" strokeWidth={2}/><Area yAxisId="right" type="monotone" dataKey="profit" stroke="#22c55e" fill="#22c55e1c" strokeWidth={2}/></>:<Area yAxisId="left" type="monotone" dataKey={trendMetric.toLowerCase()} stroke={trendMetric==='Profit'?'#22c55e':trendMetric==='Orders'?'#a78bfa':trendMetric==='Quantity'?'#f59e0b':'#3b82f6'} fill={trendMetric==='Profit'?'#22c55e1c':'#3b82f624'} strokeWidth={2}/>}</AreaChart></ResponsiveContainer></ChartCard><SegmentPerformance rows={rows} onSelect={set('segment')}/><TopCategories data={cats.slice(0,5)} onSelect={set('category')}/></div><div className="overview-signals"><ExecutiveSignals rows={rows} sales={summary.sales} profit={summary.profit}/></div></section>
 <section id="sales"><h2>Sales Analysis</h2><p className="section-description">Revenue performance and the drivers behind demand across the selected period.</p><div className="sales-kpis"><div><small>Revenue</small><strong>{money(summary.sales)}</strong></div><div><small>Orders</small><strong>{number(summary.orders)}</strong></div><div><small>Average order value</small><strong>{money(summary.sales/(summary.orders||1))}</strong></div><div><small>Leading market</small><strong>{markets[0]?.name||'—'}</strong></div></div><div className="grid two sales-grid"><ChartCard title="Revenue Trend Analysis"><p className="chart-description">Period movement for sales, profit, orders, and quantity.</p><ResponsiveContainer width="100%" height={320}><AreaChart data={monthly}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="name" minTickGap={28}/><YAxis yAxisId="left" tickFormatter={money}/><YAxis yAxisId="right" orientation="right" tickFormatter={money}/><Tooltip content={<TrendTooltip/>}/><Legend/><Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" fill="#3b82f624" strokeWidth={2}/><Area yAxisId="right" type="monotone" dataKey="profit" stroke="#22c55e" fill="#22c55e1c" strokeWidth={2}/></AreaChart></ResponsiveContainer></ChartCard><ChartCard title="Sales by Category"><p className="chart-description">Revenue concentration by product category.</p><Bars data={cats.slice(0,10)} money/></ChartCard><ChartCard title="Sales by Market"><p className="chart-description">Markets contributing the most revenue.</p><Bars data={markets} money/></ChartCard><ChartCard title="Sales by Region"><p className="chart-description">Regional sales contribution.</p><Bars data={group(rows,r=>r.region,r=>r.sales).slice(0,10)} money/></ChartCard><ChartCard title="Customer Segment Sales"><p className="chart-description">Revenue contribution by customer segment.</p><Bars data={segments} money/></ChartCard><SalesProductRanking rows={productRows}/><SalesConcentration rows={productRows} total={summary.sales}/></div><SalesInsights data={salesIntelligence}/></section>
 <ProductWorkspace products={productRows} totalSales={summary.sales} totalProfit={summary.profit} categoryFiltered={filters.category!=='All'} page={page} setPage={setPage} activeFilters={active}/>
 <section id="geography"><h2>Geographic Performance</h2><div className="geo-stats"><span>{number(markets.length)} markets</span><span>{number(new Set(rows.map(r=>r.region)).size)} regions</span><span>{number(new Set(rows.map(r=>r.country)).size)} countries</span><b>Top market: {markets[0]?.name||'—'}</b></div><GlobalSalesMap rows={rows}/><div className="grid two"><ChartCard title="Sales by Market"><Bars data={markets} money/></ChartCard><ChartCard title="Top Countries by Sales"><Bars data={countries} money/></ChartCard></div></section>
 <section id="supply-chain"><h2>Supply Chain Performance</h2><div className="grid two"><ChartCard title="Delivery Status Distribution"><ResponsiveContainer width="100%" height={290}><PieChart><Pie data={delivery} dataKey="value" nameKey="name" outerRadius={100} label>{delivery.map((_,i)=><Cell key={i} fill={colors[i]}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer></ChartCard><ChartCard title="Shipping Mode Performance"><ResponsiveContainer width="100%" height={290}><BarChart data={ship}><XAxis dataKey="name"/><YAxis/><Tooltip/><Legend/><Bar dataKey="orders" fill={colors[0]}/><Bar dataKey="days" fill={colors[2]}/></BarChart></ResponsiveContainer></ChartCard></div><DeliveryTable data={ship}/></section>
 <CustomerAnalytics rows={rows} totalSales={summary.sales} totalProfit={summary.profit} monthly={monthly} segmentFiltered={filters.segment!=='All'}/>
 <section id="profitability"><h2>Discount &amp; Profitability</h2><div className="discounts"><div><small>Average discount rate</small><strong>{pct(rows.reduce((a,r)=>a+r.discountRate,0)/(rows.length||1))}</strong></div><div><small>Total discount</small><strong>{money(rows.reduce((a,r)=>a+r.discount,0))}</strong></div><div><small>Average profit per row</small><strong>{money(summary.profit/(rows.length||1))}</strong></div></div><div className="grid two"><DiscountAnalysis rows={rows}/><ChartCard title="Profit Margin by Category"><ResponsiveContainer width="100%" height={300}><BarChart data={cats.map(c=>({name:c.name,value:(profits.find(p=>p.name===c.name)?.value||0)/c.value})).sort((a,b)=>b.value-a.value)} layout="vertical"><XAxis type="number" tickFormatter={pct}/><YAxis type="category" dataKey="name" width={110}/><Tooltip formatter={(v:number)=>pct(v)}/><Bar dataKey="value" fill={colors[1]}/></BarChart></ResponsiveContainer></ChartCard></div></section>
 <ExecutiveInsights items={insightCards}/></>}<PredictiveAnalytics/><footer className="app-footer"><div><strong>DataCo Retail Analytics</strong><span>Sales, Profitability &amp; Supply Chain Performance</span></div><div><strong>Made by Kliz John Andrei C. Millares</strong><span>Academic Project · v1.0</span></div></footer></main>}
type SegmentMetric='Sales'|'Orders'|'Profit'|'Customers';
function SegmentPerformance({rows,onSelect}:{rows:RetailRow[];onSelect:(value:string)=>void}){const [metric,setMetric]=useState<SegmentMetric>('Sales');const data=useMemo(()=>{const map=new Map<string,{name:string;sales:number;profit:number;orders:Set<string>;customers:Set<string>}>();rows.forEach(row=>{const item=map.get(row.segment)||{name:row.segment,sales:0,profit:0,orders:new Set<string>(),customers:new Set<string>()};item.sales+=row.sales;item.profit+=row.profit;item.orders.add(row.orderId);item.customers.add(row.customerId);map.set(row.segment,item)});return [...map.values()].map(item=>({...item,value:metric==='Sales'?item.sales:metric==='Profit'?item.profit:metric==='Orders'?item.orders.size:item.customers.size})).sort((a,b)=>b.value-a.value)},[rows,metric]);const total=data.reduce((sum,item)=>sum+item.value,0),format=metric==='Sales'||metric==='Profit'?money:number;return <ChartCard title="Customer Segment Performance"><div className="chart-controls"><select aria-label="Customer segment metric" value={metric} onChange={event=>setMetric(event.target.value as SegmentMetric)}>{(['Sales','Orders','Profit','Customers'] as SegmentMetric[]).map(item=><option key={item}>{item}</option>)}</select></div><p className="chart-description">{metric} contribution and order distribution across customer segments.</p><div className="segment-layout"><div className="segment-donut"><ResponsiveContainer width="100%" height={210}><PieChart><Pie data={data} dataKey="value" nameKey="name" innerRadius={57} outerRadius={82} paddingAngle={2} onClick={(item)=>onSelect(item.name)}>{data.map((item,index)=><Cell key={item.name} fill={['#60a5fa','#a78bfa','#38bdf8'][index]}/>)}</Pie><Tooltip formatter={(value:number)=>format(value)} /></PieChart></ResponsiveContainer><div className="donut-total"><strong>{format(total)}</strong><span>Total {metric}</span></div></div><div className="segment-legend">{data.map((item,index)=><button key={item.name} onClick={()=>onSelect(item.name)}><i style={{background:['#60a5fa','#a78bfa','#38bdf8'][index]}}/><span>{item.name}</span><b>{(item.value/(total||1)*100).toFixed(1)}%</b><small>{format(item.value)}</small></button>)}</div></div></ChartCard>}
type CategoryMetric='Sales'|'Profit'|'Quantity'|'Margin';
function SalesInsights({data}:{data:SalesIntelligence}){const {topCategory,runnerUp,topProduct,concentration,momentum,concentrationLabel,concentrationTone,concentrationMeaning,categoryFiltered}=data,canCompare=!!topCategory&&!!runnerUp&&!categoryFiltered,gap=canCompare?(topCategory.value-runnerUp.value):0,gapPercent=canCompare?gap/(runnerUp.value||1):0,MomentumIcon=momentum?.state==='accelerating'||momentum?.state==='growing'?TrendingUp:momentum?.state==='softening'||momentum?.state==='declining'?TrendingDown:Activity,values=momentum?.spark||[],min=Math.min(...values),max=Math.max(...values),points=values.map((value,index)=>`${values.length>1?index/(values.length-1)*100:0},${max===min?20:40-(value-min)/(max-min)*36}`).join(' ');return <section className="sales-insights sales-intelligence" aria-labelledby="sales-insights-title"><div className="sales-insights-heading"><div><h3 id="sales-insights-title">Sales Insights</h3><p>Revenue leaders, concentration, and sales opportunities</p></div><span>Filtered view</span></div><div className="sales-intelligence-grid"><article className="sales-intelligence-card category"><div className="sales-intelligence-icon"><Tags size={17}/></div><div><span>Top category</span><strong>{topCategory?.name||'—'}</strong><b>{money(topCategory?.value||0)}</b><small>{categoryFiltered?'Current selection':runnerUp?`vs. ${runnerUp.name} · ${money(runnerUp.value)}`:'No category comparison available'}</small></div></article><article className="sales-intelligence-card product"><div className="sales-intelligence-icon"><Package size={17}/></div><div><span>Top product</span><strong title={topProduct?.name}>{topProduct?.name||'—'}</strong><b>{money(topProduct?.sales||0)}</b><small>Highest-selling product</small></div></article><article className="sales-intelligence-card concentration"><div className="sales-intelligence-icon"><Target size={17}/></div><div><span>Top 10 concentration</span><strong>{pct(concentration)}</strong><i className="concentration-meter"><b style={{width:`${Math.min(100,concentration*100)}%`}}/></i><small>of selected revenue</small></div></article><article className="sales-intelligence-card gap"><div className="sales-intelligence-icon"><TrendingUp size={17}/></div><div><span>Revenue leader gap</span><strong>{canCompare?`${topCategory.name} vs. ${runnerUp.name}`:'Insufficient data'}</strong><b>{canCompare?`+${money(gap)} · +${pct(gapPercent)}`:'Comparison unavailable'}</b><small>{categoryFiltered?'Category-filtered selection':canCompare?'Difference from the next category':'Need two unfiltered categories'}</small></div></article><article className={`sales-intelligence-card risk ${concentrationTone}`}><div className="sales-intelligence-icon"><TriangleAlert size={17}/></div><div><span>Concentration risk</span><strong>{concentrationLabel}</strong><b>{pct(concentration)} top-10 share</b><small>{concentrationTone==='low'?'Broad revenue distribution':concentrationTone==='moderate'?'Balanced leading-product mix':'Monitor reliance on leading products'}</small></div></article><article className={`sales-intelligence-card momentum ${momentum?.state||'stable'}`}><div className="sales-intelligence-icon"><MomentumIcon size={17}/></div><div><span>Sales momentum</span><strong>{momentum?momentum.state[0].toUpperCase()+momentum.state.slice(1):'Insufficient data'}</strong>{momentum?<><b>{momentum.change>=0?'+':''}{pct(momentum.change)}</b><small>{momentum.latest} vs. {momentum.previous}</small><svg className="momentum-spark" viewBox="0 0 100 40" preserveAspectRatio="none" aria-label="Recent sales movement"><polyline points={points}/></svg></>:<small>Not enough periods for comparison</small>}</div></article></div><aside className={`sales-meaning ${concentrationTone}`}><span>What this means</span><p>{concentrationMeaning}</p></aside></section>}
function DiscountAnalysis({rows}:{rows:RetailRow[]}){const [metric,setMetric]=useState<'profit'|'sales'|'margin'>('profit'),bands=useMemo(()=>{const bins=[0,.05,.1,.15,.2,.25,.3,Infinity].map((start,index)=>({name:index===0?'0%':index===7?'30%+':`${start*100}–${[.05,.1,.15,.2,.25,.3][index-1]*100}%`,start,end:[.05,.1,.15,.2,.25,.3,Infinity][index]||Infinity,sales:0,profit:0,orders:new Set<string>(),transactions:0}));rows.forEach(row=>{const bin=bins.find(item=>row.discountRate>=item.start&&row.discountRate<item.end);if(bin){bin.sales+=row.sales;bin.profit+=row.profit;bin.orders.add(row.orderId);bin.transactions++}});return bins.filter(bin=>bin.transactions).map(bin=>({...bin,orders:bin.orders.size,margin:bin.profit/(bin.sales||1)}))},[rows]);return <ChartCard title="Discount & Profitability Analysis"><p className="chart-description">How discounting affects revenue, profit, and margin.</p><div className="metric-switch">{(['profit','sales','margin'] as const).map(item=><button className={metric===item?'active':''} key={item} onClick={()=>setMetric(item)}>{item}</button>)}</div>{bands.length?<ResponsiveContainer width="100%" height={300}><ComposedChart data={bands}><XAxis dataKey="name"/><YAxis yAxisId="value" tickFormatter={metric==='margin'?pct:money}/><YAxis yAxisId="margin" orientation="right" tickFormatter={pct}/><Tooltip formatter={(v:number,key)=>key==='margin'?pct(v):fullMoney(v)}/><Bar yAxisId="value" dataKey={metric} fill={metric==='sales'?'#3b82f6':metric==='margin'?'#8b5cf6':'#22c55e'}/><Line yAxisId="margin" dataKey="margin" stroke="#8b5cf6" strokeWidth={2}/></ComposedChart></ResponsiveContainer>:<p className="insights-empty">Insufficient data for discount profitability analysis.</p>}</ChartCard>}
function CustomerValueMatrix({customers,salesMedian,profitMedian}:{customers:{id:string;segment:string;sales:number;profit:number;orders:number;margin:number}[];salesMedian:number;profitMedian:number}){const points=customers.slice(0,1500),colors:Record<string,string>={Consumer:'#06b6d4',Corporate:'#3b82f6','Home Office':'#8b5cf6'};return <ChartCard title="Customer Value Matrix" className="customer-value-matrix"><p className="chart-description">Customer-level revenue, profitability, and order activity. Median reference lines define value quadrants.</p><ResponsiveContainer width="100%" height={350}><ScatterChart><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="sales" type="number" tickFormatter={money}/><YAxis dataKey="profit" type="number" tickFormatter={money}/><Tooltip formatter={(v:number)=>fullMoney(v)}/>{Object.keys(colors).map(segment=><Scatter key={segment} data={points.filter(point=>point.segment===segment)} fill={colors[segment]}/>)}</ScatterChart></ResponsiveContainer><div className="matrix-caption">High value: sales ≥ {money(salesMedian)} and profit ≥ {money(profitMedian)} · showing up to 1,500 aggregated customers</div></ChartCard>}
function ProductWorkspace({products,totalSales,totalProfit,categoryFiltered,page,setPage,activeFilters}:{products:ProductRow[];totalSales:number;totalProfit:number;categoryFiltered:boolean;page:number;setPage:(value:number)=>void;activeFilters:number}){const model=useMemo(()=>{const top=products[0],second=products[1],salesMedian=[...products].map(item=>item.sales).sort((a,b)=>a-b)[Math.floor(products.length/2)]||0,profitMedian=[...products].map(item=>item.profit).sort((a,b)=>a-b)[Math.floor(products.length/2)]||0,health={invest:0,fix:0,grow:0,review:0};products.forEach(item=>{if(item.sales>=salesMedian&&item.profit>=profitMedian)health.invest++;else if(item.sales>=salesMedian)health.fix++;else if(item.profit>=profitMedian)health.grow++;else health.review++});const marginOpportunity=[...products].filter(item=>item.sales>=salesMedian).sort((a,b)=>a.profit/(a.sales||1)-b.profit/(b.sales||1))[0],hiddenProfit=[...products].filter(item=>item!==top).sort((a,b)=>b.profit-a.profit)[0];return{top,second,health,marginOpportunity,hiddenProfit,concentration:products.slice(0,10).reduce((sum,item)=>sum+item.sales,0)/(totalSales||1)}},[products,totalSales]);const gap=model.top&&model.second?model.top.sales-model.second.sales:undefined;return <section id="products" className="product-workspace"><div className="customer-page-heading"><div><h2>Product Performance</h2><p>Product portfolio performance, profitability, and opportunity analysis.</p></div></div><div className="customer-kpis"><div><span>Products</span><strong>{number(products.length)}</strong></div><div><span>Product sales</span><strong>{money(totalSales)}</strong></div><div><span>Product profit</span><strong>{money(totalProfit)}</strong></div><div><span>Avg. product revenue</span><strong>{money(totalSales/(products.length||1))}</strong></div><div><span>{categoryFiltered?'Current product':'Top product'}</span><strong title={model.top?.name}>{model.top?.name||'—'}</strong></div><div><span>Top product share</span><strong>{pct((model.top?.sales||0)/(totalSales||1))}</strong></div></div><h3 className="customer-section-title">Product Leaders</h3><div className="grid two"><ChartCard title="Top 10 Products by Sales"><Bars data={products.slice(0,10).map(item=>({name:item.name,value:item.sales}))} money/></ChartCard><ChartCard title="Top 10 Products by Profit" className="chart-profit"><Bars data={[...products].sort((a,b)=>b.profit-a.profit).slice(0,10).map(item=>({name:item.name,value:item.profit}))} profit/></ChartCard></div><div className="customer-intelligence"><article><span>Revenue concentration</span><strong>Top 10 products</strong><b>{pct(model.concentration)}</b><i><em style={{width:`${Math.min(100,model.concentration*100)}%`}}/></i><small>of selected product revenue</small></article><article><span>Product leader gap</span><strong>{gap===undefined?'Insufficient data':`${model.top?.name} vs. ${model.second?.name}`}</strong><b>{gap===undefined?'Comparison unavailable':`+${money(gap)}`}</b><small>{gap===undefined?'Need two products for comparison':`${pct(gap/(model.second?.sales||1))} ahead of #2`}</small></article><article><span>Margin opportunity</span><strong>{model.marginOpportunity?.name||'—'}</strong><b>{pct((model.marginOpportunity?.profit||0)/(model.marginOpportunity?.sales||1))} margin</b><small>{money(model.marginOpportunity?.sales||0)} high-revenue sales</small></article></div><section className="portfolio-health"><h3>Portfolio Health</h3><p>Notebook-aligned sales and profit quadrants for the filtered product portfolio.</p>{Object.entries(model.health).map(([name,count])=><div key={name}><span>{name.replace(/(^| )\w/g,letter=>letter.toUpperCase())}</span><b>{count} products</b><i><em style={{width:`${count/(products.length||1)*100}%`}}/></i></div>)}</section><OpportunityMatrix products={products}/><ProductTable rows={products} page={page} setPage={setPage} activeFilters={activeFilters}/><div className="customer-intelligence"><article><span>Top revenue driver</span><strong>{model.top?.name||'—'}</strong><b>{money(model.top?.sales||0)}</b><small>Highest filtered product revenue</small></article><article><span>Hidden profit driver</span><strong>{model.hiddenProfit?.name||'—'}</strong><b>{money(model.hiddenProfit?.profit||0)} profit</b><small>{pct((model.hiddenProfit?.profit||0)/(model.hiddenProfit?.sales||1))} margin</small></article><article><span>Portfolio health</span><strong>{model.health.invest} invest</strong><b>{pct(model.health.invest/(products.length||1))}</b><small>Products in the high-sales, high-profit quadrant</small></article></div></section>}
function CustomerAnalytics({rows,totalSales,totalProfit,monthly,segmentFiltered}:{rows:RetailRow[];totalSales:number;totalProfit:number;monthly:{name:string;sales:number}[];segmentFiltered:boolean}){const model=useMemo(()=>{const m=new Map<string,{id:string;segment:string;sales:number;profit:number;orders:Set<string>}>();rows.forEach(r=>{const x=m.get(r.customerId)||{id:r.customerId,segment:r.segment,sales:0,profit:0,orders:new Set<string>()};x.sales+=r.sales;x.profit+=r.profit;x.orders.add(r.orderId);m.set(r.customerId,x)});const customers=[...m.values()].map(x=>({...x,orders:x.orders.size,margin:x.profit/(x.sales||1)}));const sales=[...m.values()].map(x=>x.sales).sort((a,b)=>a-b),profit=[...m.values()].map(x=>x.profit).sort((a,b)=>a-b),salesMedian=sales[Math.floor(sales.length/2)]||0,profitMedian=profit[Math.floor(profit.length/2)]||0;return{customers,salesMedian,profitMedian,top:customers.sort((a,b)=>b.sales-a.sales)[0]}},[rows]);return <section id="customers" className="customer-analytics"><div className="customer-page-heading"><h2>Customer Analytics</h2><p>Customer value, segment performance, and customer intelligence.</p></div><div className="customer-kpis"><div><span>Total customers</span><strong>{number(model.customers.length)}</strong></div><div><span>Customer sales</span><strong>{money(totalSales)}</strong></div><div><span>Customer profit</span><strong>{money(totalProfit)}</strong></div><div><span>Avg. customer revenue</span><strong>{money(totalSales/(model.customers.length||1))}</strong></div><div><span>Avg. order value</span><strong>{money(totalSales/(new Set(rows.map(r=>r.orderId)).size||1))}</strong></div><div><span>{segmentFiltered?'Current segment':'Top customer'}</span><strong>{segmentFiltered?'Filtered':model.top?.id||'—'}</strong></div></div><div className="grid two"><ChartCard title="Customer Segment Sales"><Bars data={group(rows,r=>r.segment,r=>r.sales)} money/></ChartCard><ChartCard title="Customer Segment Profit" className="chart-profit"><Bars data={group(rows,r=>r.segment,r=>r.profit)} profit/></ChartCard></div><CustomerValueMatrix customers={model.customers} salesMedian={model.salesMedian} profitMedian={model.profitMedian}/><ChartCard title="Customer Sales Trend"><ResponsiveContainer width="100%" height={260}><AreaChart data={monthly}><XAxis dataKey="name"/><YAxis tickFormatter={money}/><Tooltip formatter={(v:number)=>fullMoney(v)}/><Area dataKey="sales" type="monotone" stroke="#06b6d4" fill="#06b6d422"/></AreaChart></ResponsiveContainer></ChartCard></section>}
function ExecutiveInsights({items}:{items:InsightCardData[]}){return <section className="insights executive-insights" aria-labelledby="key-insights-title"><div className="insights-heading"><div><h2 id="key-insights-title">Key Insights</h2><p>Executive takeaways from the current filtered data</p></div><span>{items.length} live signals</span></div>{items.length?<div className="insight-grid">{items.map(({tone,label,entity,metric,context,Icon})=><article className={`insight-card insight-${tone}`} key={label}><div className="insight-icon"><Icon size={16}/></div><div><span className="insight-label">{label}</span><strong>{entity}</strong><b>{metric}</b><small>{context}</small></div></article>)}</div>:<p className="insights-empty">No insights are available for the current filters.</p>}</section>}
function CategoryPerformance({rows,onSelect}:{rows:RetailRow[];onSelect:(value:string)=>void}){const [metric,setMetric]=useState<CategoryMetric>('Sales');const data=useMemo(()=>{const map=new Map<string,{name:string;sales:number;profit:number;quantity:number;orders:Set<string>}>();rows.forEach(row=>{const item=map.get(row.category)||{name:row.category,sales:0,profit:0,quantity:0,orders:new Set<string>()};item.sales+=row.sales;item.profit+=row.profit;item.quantity+=row.quantity;item.orders.add(row.orderId);map.set(row.category,item)});return [...map.values()].map(item=>({...item,value:metric==='Sales'?item.sales:metric==='Profit'?item.profit:metric==='Quantity'?item.quantity:item.profit/(item.sales||1)})).sort((a,b)=>b.value-a.value).slice(0,10)},[rows,metric]);const top=data[0],format=metric==='Sales'||metric==='Profit'?money:metric==='Margin'?pct:number;return <ChartCard title="Category Performance"><div className="metric-switch" role="group" aria-label="Category performance metric">{(['Sales','Profit','Quantity','Margin'] as CategoryMetric[]).map(item=><button key={item} className={metric===item?'active':''} onClick={()=>setMetric(item)}>{item}</button>)}</div><p className="chart-description">Ranked category contribution for the current selection. Select a bar to filter the workspace.</p><ResponsiveContainer width="100%" height={250}><BarChart data={data} layout="vertical" margin={{left:8,right:28}}><XAxis type="number" tickFormatter={format}/><YAxis dataKey="name" type="category" width={122} tick={{fontSize:11}}/><Tooltip formatter={(value:number)=>format(value)} labelFormatter={label=>String(label)} /><Bar dataKey="value" fill={metric==='Profit'||metric==='Margin'?'#22c55e':metric==='Quantity'?'#94a3b8':'#3b82f6'} radius={[0,4,4,0]} onClick={(item)=>onSelect(item.name)}/></BarChart></ResponsiveContainer>{top&&<p className="category-insight"><span>Top category</span><b>{top.name}</b> leads {metric.toLowerCase()} at {format(top.value)}.</p>}</ChartCard>}
