function ExecutiveSignals({rows,sales,profit}:{rows:RetailRow[];sales:number;profit:number}){const category=new Map<string,{sales:number;profit:number}>(),ship=new Map<string,{late:number;count:number}>();rows.forEach(row=>{const c=category.get(row.category)||{sales:0,profit:0};c.sales+=row.sales;c.profit+=row.profit;category.set(row.category,c);const s=ship.get(row.shippingMode)||{late:0,count:0};s.late+=row.late;s.count++;ship.set(row.shippingMode,s)});const best=[...category].filter(([,value])=>value.sales>0).sort((a,b)=>b[1].profit/b[1].sales-a[1].profit/a[1].sales)[0],risk=[...ship].sort((a,b)=>b[1].late/b[1].count-a[1].late/a[1].count)[0],margin=profit/(sales||1),late=rows.filter(row=>row.late===1).length/(rows.length||1);return <><article><span>Profitability signal</span><strong>{money(profit)}</strong><p>Average margin <b>{pct(margin)}</b> · Top margin category <b>{best?.[0]||'—'}</b></p></article><article className="risk-signal"><span>Supply chain signal</span><strong>{pct(late)} late</strong><p>Highest-risk shipping mode <b>{risk?.[0]||'—'}</b></p><a href="#supply-chain">View Supply Chain →</a></article></>}
type ChartTone='sales'|'profit'|'orders'|'customers'|'financial'|'risk'|'margin';const chartPalette:Record<ChartTone,[string,string]>={sales:['#3B82F6','#60A5FA'],profit:['#22C55E','#4ADE80'],orders:['#8B5CF6','#A78BFA'],customers:['#06B6D4','#22D3EE'],financial:['#F59E0B','#FBBF24'],risk:['#EF4444','#F87171'],margin:['#14B8A6','#2DD4BF']};
function Bars({data,money:currency=false,profit=false,tone}:{data:{name:string;value:number}[];money?:boolean;profit?:boolean;tone?:ChartTone}){const resolvedTone=tone||(profit?'profit':'sales'),[color,secondary]=chartPalette[resolvedTone],format=(value:number)=>currency||profit?fullMoney(value):number(value);return <ResponsiveContainer width="100%" height={272}><BarChart data={data} layout="vertical" margin={{top:4,right:52,bottom:4,left:6}}><defs><linearGradient id={`ranked-bar-${resolvedTone}`} x1="0" x2="1"><stop offset="0%" stopColor={color}/><stop offset="100%" stopColor={secondary}/></linearGradient></defs><CartesianGrid strokeDasharray="3 5" horizontal={false} vertical stroke="#29405b" strokeOpacity={.52}/><XAxis type="number" axisLine={false} tickLine={false} tickFormatter={format}/><YAxis dataKey="name" type="category" width={132} axisLine={false} tickLine={false} tick={{fontSize:11}}/><Tooltip cursor={{fill:`${secondary}12`}} content={<RankedTooltip format={format} metric={profit?'Profit':currency?'Sales':'Count'}/>}/><Bar dataKey="value" fill={`url(#ranked-bar-${resolvedTone})`} radius={[0,6,6,0]} maxBarSize={18} isAnimationActive animationDuration={420}>{profit&&data.map((x,i)=><Cell key={i} fill={x.value<0?chartPalette.risk[0]:undefined}/>) }<LabelList dataKey="value" position="right" formatter={(value:number)=>format(value)} className="ranked-value-label"/></Bar></BarChart></ResponsiveContainer>}
function RankedTooltip({active,payload,label,format,metric}:{active?:boolean;payload?:{value?:number;color?:string}[];label?:string;format:(value:number)=>string;metric:string}){return active&&payload?.length?<div className="ranked-tooltip"><strong>{label}</strong><span><i style={{background:payload[0].color}}/>{metric}<b>{format(payload[0].value||0)}</b></span></div>:null}
type ProductRow={name:string;category:string;sales:number;profit:number;quantity:number};type SortKey='name'|'category'|'sales'|'profit'|'quantity'|'margin';
function ProductTable({rows,page,setPage,activeFilters}:{rows:ProductRow[];page:number;setPage:(n:number)=>void;activeFilters:number}){const [query,setQuery]=useState(''),[sort,setSort]=useState<{key:SortKey;direction:'asc'|'desc'}>({key:'sales',direction:'desc'}),[selected,setSelected]=useState('');const per=10,thresholds=useMemo(()=>marginThresholds(rows),[rows]);const visible=useMemo(()=>rows.filter(row=>`${row.name} ${row.category}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>{const av=sort.key==='margin'?a.profit/(a.sales||1):a[sort.key],bv=sort.key==='margin'?b.profit/(b.sales||1):b[sort.key];return (typeof av==='string'?av.localeCompare(bv as string):(av as number)-(bv as number))*(sort.direction==='asc'?1:-1)}),[rows,query,sort]);const pages=Math.ceil(visible.length/per)||1,actualPage=Math.min(page,pages-1),items=visible.slice(actualPage*per,actualPage*per+per);const changeSort=(key:SortKey)=>{setSort(current=>({key,direction:current.key===key&&current.direction==='desc'?'asc':'desc'}));setPage(0)};const head=(label:string,key:SortKey)=><th className={sort.key===key?'sorted':''}><button onClick={()=>changeSort(key)}>{label}<i>{sort.key===key?(sort.direction==='desc'?'↓':'↑'):'↕'}</i></button></th>;return <ChartCard title="Product Performance"><div className="table-heading"><div><p className="table-eyebrow">Performance details</p><p className="chart-description">Top products by sales, profit, quantity, and margin.</p></div><label className="product-search"><span>Search products</span><input value={query} onChange={event=>{setQuery(event.target.value);setPage(0)}} placeholder="Search products..."/></label></div><div className="table-meta"><span>Showing {number(visible.length)} products</span>{activeFilters>0&&<span className="filter-state">Filtered selection · {activeFilters} active</span>}</div><div className="table-wrap"><table className="product-table"><thead><tr>{head('Product','name')}{head('Category','category')}{head('Sales','sales')}{head('Profit','profit')}{head('Quantity','quantity')}{head('Margin','margin')}</tr></thead><tbody>{items.map((row,index)=>{const margin=row.profit/(row.sales||1),tone=marginTone(margin,thresholds);return <tr key={row.name} className={selected===row.name?'selected':''} onClick={()=>setSelected(row.name)}><td><span className="rank">{String(actualPage*per+index+1).padStart(2,'0')}</span>{row.name}</td><td>{row.category}</td><td className="sales-value">{fullMoney(row.sales)}</td><td className={row.profit<0?'profit-value negative':'profit-value'}>{fullMoney(row.profit)}</td><td className="quantity-value">{number(row.quantity)}</td><td><span className={`margin-badge ${tone}`}>{pct(margin)}</span></td></tr>})}</tbody></table></div><div className="pagination"><button disabled={actualPage===0} onClick={()=>setPage(actualPage-1)}>Previous</button><span>Page {actualPage+1} of {pages}</span><button disabled={(actualPage+1)*per>=visible.length} onClick={()=>setPage(actualPage+1)}>Next</button></div></ChartCard>}
function DeliveryTable({data}:{data:{name:string;orders:number;days:number;late:number}[]}){return <ChartCard title="Delivery Performance"><div className="table-wrap"><table><thead><tr><th>Shipping Mode</th><th>Orders</th><th>Avg. Shipping Days</th><th>Late Delivery Rate</th></tr></thead><tbody>{data.map(x=><tr key={x.name}><td>{x.name}</td><td>{number(x.orders)}</td><td>{x.days.toFixed(1)}</td><td>{pct(x.late)}</td></tr>)}</tbody></table></div></ChartCard>}
